    arr: k => { const LT = T_arr; let z = 0, c = 0, s = 0; for (let i = 0; i < k; ++i) { const a = (i & 1023) * .00306; const t = a * 40.74366543152521, i = t | 0, u = t - i, j = 2 * i, c0 = LT[j], s0 = LT[j + 1]; c = c0 + (LT[j + 2] - c0) * u; s = s0 + (LT[j + 3] - s0) * u; z += c + s; } sink = z; },
    f64: k => { const LT = T_f64; let z = 0, c = 0, s = 0; for (let i = 0; i < k; ++i) { const a = (i & 1023) * .00306; const t = a * 40.74366543152521, i = t | 0, u = t - i, j = 2 * i, c0 = LT[j], s0 = LT[j + 1]; c = c0 + (LT[j + 2] - c0) * u; s = s0 + (LT[j + 3] - s0) * u; z += c + s; } sink = z; },
    f32: k => { const LT = T_f32; let z = 0, c = 0, s = 0; for (let i = 0; i < k; ++i) { const a = (i & 1023) * .00306; const t = a * 40.74366543152521, i = t | 0, u = t - i, j = 2 * i, c0 = LT[j], s0 = LT[j + 1]; c = c0 + (LT[j + 2] - c0) * u; s = s0 + (LT[j + 3] - s0) * u; z += c + s; } sink = z; },
    i16: k => { const LT = T_i16; let z = 0, c = 0, s = 0; for (let i = 0; i < k; ++i) { const a = (i & 1023) * .00306; const t = a * 40.74366543152521, i = t | 0, u = t - i, j = 2 * i, c0 = LT[j], s0 = LT[j + 1]; c = (c0 + (LT[j + 2] - c0) * u) * 6.103515625e-5; s = (s0 + (LT[j + 3] - s0) * u) * 6.103515625e-5; z += c + s; } sink = z; },
    sin1: k => { const LT = T_sin1; let z = 0, c = 0, s = 0; for (let i = 0; i < k; ++i) { const a = (i & 1023) * .00306; const t = a * 40.74366543152521, i = t | 0, u = t - i, k = i + 64, s0 = LT[i], c0 = LT[k]; s = s0 + (LT[i + 1] - s0) * u; c = c0 + (LT[k + 1] - c0) * u; z += c + s; } sink = z; },
    qw: k => { const LT = T_qw; let z = 0, c = 0, s = 0; for (let i = 0; i < k; ++i) { const a = (i & 1023) * .00306; const t = a * 40.74366543152521, h = 64, x = t < h ? t : 128 - t, y = t < h ? h - t : t - h, i = x | 0, k = y | 0, s0 = LT[i], c0 = LT[k];
      s = s0 + (LT[i + 1] - s0) * (x - i); c = (c0 + (LT[k + 1] - c0) * (y - k)) * (t < h ? 1 : -1); z += c + s; } sink = z; },
    tay: k => { const LT = T_tay; let z = 0, c = 0, s = 0; for (let i = 0; i < k; ++i) { const a = (i & 1023) * .00306; const i = (a * 10.185916357881302 + .5) | 0, h = a - i * 0.09817477042468103, g = h * h * .5, j = 2 * i, C = LT[j], S = LT[j + 1]; c = C - h * S - g * C; s = S + h * C - g * S; z += c + s; } sink = z; },
    str: k => { const LT = T_str; let z = 0, c = 0, s = 0; for (let i = 0; i < k; ++i) { const a = (i & 1023) * .00306; const t = a * 40.74366543152521, i = t | 0, u = t - i, j = 2 * i, c0 = LT.charCodeAt(j) << 16 >> 16, s0 = LT.charCodeAt(j + 1) << 16 >> 16; c = (c0 + ((LT.charCodeAt(j + 2) << 16 >> 16) - c0) * u) * 6.103515625e-5; s = (s0 + ((LT.charCodeAt(j + 3) << 16 >> 16) - s0) * u) * 6.103515625e-5; z += c + s; } sink = z; },
    ptabArr: k => { const LT = T_ptabArr; let z = 0, c = 0, s = 0; for (let i = 0; i < k; ++i) { const a = (i & 1023) * .00306; const j = 4 * (a | 0); c = LT[j] + LT[j + 1]; s = LT[j + 2] + LT[j + 3]; z += c + s; } sink = z; },
    ptab64: k => { const LT = T_ptab64; let z = 0, c = 0, s = 0; for (let i = 0; i < k; ++i) { const a = (i & 1023) * .00306; const j = 4 * (a | 0); c = LT[j] + LT[j + 1]; s = LT[j + 2] + LT[j + 3]; z += c + s; } sink = z; },
    ptab32: k => { const LT = T_ptab32; let z = 0, c = 0, s = 0; for (let i = 0; i < k; ++i) { const a = (i & 1023) * .00306; const j = 4 * (a | 0); c = LT[j] + LT[j + 1]; s = LT[j + 2] + LT[j + 3]; z += c + s; } sink = z; },
    ptabObj: k => { const LT = T_ptabObj; let z = 0, c = 0, s = 0; for (let i = 0; i < k; ++i) { const a = (i & 1023) * .00306; const e = LT[a | 0]; c = e[0] + e[1]; s = e[2] + e[3]; z += c + s; } sink = z; },
